function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  level1Url: 'https://httpbin.org/post',
  level2Url: 'https://httpbin.org/post',
  level3Url: 'https://httpbin.org/post',
  timeoutMs: 15000,
  // SLA targets in minutes by severity
  slaTargets: {
    critical: { response: 15, resolution: 240 },
    high:     { response: 60, resolution: 480 },
    medium:   { response: 240, resolution: 1440 },
    low:      { response: 480, resolution: 2880 }
  },
  atRiskThresholdPercent: 75,
  allowSimulation: true
};

const hook = ref('Webhook - Incident / Ticket Intake');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const ticketId = String(body.ticketId || body.id || ('TKT-' + Date.now())).trim();
const title = String(body.title || body.summary || '').trim();
const severity = String(body.severity || body.priority || 'medium').toLowerCase();
const createdAt = body.createdAt ? new Date(body.createdAt) : new Date();
const assignee = String(body.assignee || body.owner || '').trim();
const customer = String(body.customer || body.account || '').trim();

if (!title) errors.push('title is required');
if (!['critical', 'high', 'medium', 'low'].includes(severity)) errors.push('severity must be critical|high|medium|low');

const valid = errors.length === 0;
const targets = CONFIG.slaTargets[severity] || CONFIG.slaTargets.medium;

const responseDeadline = new Date(createdAt.getTime() + targets.response * 60 * 1000);
const resolutionDeadline = new Date(createdAt.getTime() + targets.resolution * 60 * 1000);

let level1Url = CONFIG.level1Url;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  level1Url = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    ticket: {
      ticketId,
      title,
      severity,
      createdAt: createdAt.toISOString(),
      assignee: assignee || null,
      customer: customer || null
    },
    sla: {
      responseMinutes: targets.response,
      resolutionMinutes: targets.resolution,
      responseDeadline: responseDeadline.toISOString(),
      resolutionDeadline: resolutionDeadline.toISOString()
    },
    urls: {
      level1: level1Url,
      level2: CONFIG.level2Url,
      level3: CONFIG.level3Url
    },
    requestId: body.requestId || ('sla-' + Date.now())
  }
}];

