const ctx = ref('Code - Validate & Calculate SLA');
const now = new Date();
const created = new Date(ctx.ticket.createdAt);
const respDeadline = new Date(ctx.sla.responseDeadline);
const resDeadline = new Date(ctx.sla.resolutionDeadline);

const elapsedMs = now - created;
const respTotalMs = respDeadline - created;
const resTotalMs = resDeadline - created;

const respPercent = Math.min(100, Math.round((elapsedMs / respTotalMs) * 100));
const resPercent = Math.min(100, Math.round((elapsedMs / resTotalMs) * 100));

let status = 'on_track';
if (now > resDeadline) status = 'breached_resolution';
else if (now > respDeadline) status = 'breached_response';
else if (respPercent >= ctx.config.atRiskThresholdPercent || resPercent >= ctx.config.atRiskThresholdPercent) status = 'at_risk';

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    ticket: ctx.ticket,
    sla: ctx.sla,
    urls: ctx.urls,
    breach: {
      status,
      responsePercentUsed: respPercent,
      resolutionPercentUsed: resPercent,
      isBreached: status.startsWith('breached'),
      isAtRisk: status === 'at_risk'
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Detect Breach Status');
const sev = ctx.ticket.severity;
const breach = ctx.breach;

const levels = [];
const actions = [];

// Always start with Level 1 for anything not on_track
if (breach.status !== 'on_track') {
  levels.push(1);
  actions.push({ level: 1, action: 'notify_assignee', channel: 'email+slack' });
}

if (breach.isAtRisk || breach.isBreached || sev === 'high' || sev === 'critical') {
  levels.push(2);
  actions.push({ level: 2, action: 'notify_manager_reassign', channel: 'email+pager' });
}

if (breach.isBreached || sev === 'critical') {
  levels.push(3);
  actions.push({ level: 3, action: 'executive_alert_warroom', channel: 'pager+sms' });
}

// If fully on track, no escalation
if (levels.length === 0) {
  actions.push({ level: 0, action: 'none', channel: null });
}

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    ticket: ctx.ticket,
    sla: ctx.sla,
    urls: ctx.urls,
    breach: ctx.breach,
    plan: {
      levels,
      actions,
      maxLevel: levels.length ? Math.max(...levels) : 0
    },
    results: {}
  }
}];

