const ctx = ref('Code - Build Escalation Plan');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const needed = (ctx.plan.levels || []).includes(1);
const ok = !needed || (status >= 200 && status < 300);

const results = {
  ...ctx.results,
  level1: { required: needed, ok, status, executedAt: new Date().toISOString() }
};

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    ticket: ctx.ticket,
    sla: ctx.sla,
    urls: ctx.urls,
    breach: ctx.breach,
    plan: ctx.plan,
    results,
    continueToL2: ok && (ctx.plan.levels || []).includes(2)
  }
}];

