function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process Level 3');

const executedLevels = Object.entries(ctx.results || {})
  .filter(([_, v]) => v.required)
  .map(([k, v]) => ({ level: k, ok: v.ok, status: v.status, executedAt: v.executedAt }));

const allOk = executedLevels.every(l => l.ok);

const report = {
  requestId: ctx.requestId,
  ticketId: ctx.ticket.ticketId,
  title: ctx.ticket.title,
  severity: ctx.ticket.severity,
  sla: ctx.sla,
  breach: ctx.breach,
  plan: {
    levels: ctx.plan.levels,
    maxLevel: ctx.plan.maxLevel
  },
  actionsExecuted: executedLevels,
  overallSuccess: allOk,
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    requestId: ctx.requestId,
    report,
    overallSuccess: allOk
  }
}];

